using System.Text;
using System.Text.Json.Nodes;
using Teleport.Core;
using Xunit;

namespace Teleport.Core.Tests;

/// Cross-platform conformance: protocol/vectors.json is generated by the TS reference,
/// and the Swift and Kotlin implementations pass the same file.
public class VectorTests
{
    internal static readonly JsonNode V = JsonNode.Parse(File.ReadAllText(FindVectors()))!;

    private static string FindVectors()
    {
        for (var dir = new DirectoryInfo(AppContext.BaseDirectory); dir is not null; dir = dir.Parent)
        {
            var candidate = Path.Combine(dir.FullName, "protocol", "vectors.json");
            if (File.Exists(candidate)) return candidate;
        }
        throw new FileNotFoundException("protocol/vectors.json");
    }

    internal static byte[] B(JsonNode? n) => B64.FromUrl(n!.GetValue<string>());
    internal static string S(JsonNode? n) => n!.GetValue<string>();
    private static Envelope Env(JsonNode n) => Envelope.Parse(n.ToJsonString());
    private static long Now => V["now"]!.GetValue<long>();

    private static readonly SoftwareAgreementKey Recipient = SoftwareAgreementKey.FromRaw(B(V["recipient_ka"]!["d"]), B(V["recipient_ka"]!["pub"]));
    private static readonly SoftwareSigningKey Sender = SoftwareSigningKey.FromRaw(B(V["sender_ks"]!["d"]), B(V["sender_ks"]!["pub"]));

    [Fact]
    public void Fingerprint() => Assert.Equal(S(V["sender_ks"]!["fp"]), TeleportCrypto.Fingerprint(Sender.PublicKey));

    [Fact]
    public void OpensEveryCase()
    {
        foreach (var c in V["cases"]!.AsArray())
        {
            var pt = TeleportCrypto.Open(Env(c!["env"]!), Recipient, Sender.PublicKey, Now);
            Assert.Equal(S(c["plaintext"]), B64.Url(pt));
        }
    }

    [Fact]
    public void SealMatchesEveryCase()
    {
        foreach (var c in V["cases"]!.AsArray())
        {
            var expected = Env(c!["env"]!);
            using var eph = SoftwareAgreementKey.FromRaw(B(c["eph"]!["d"]), B(c["eph"]!["pub"]));
            var env = TeleportCrypto.Seal(expected.K, B(c["plaintext"]), Sender, Recipient.PublicKey,
                id: B64.FromUrl(expected.Id), ts: expected.Ts, ephemeral: eph, nonce: B64.FromUrl(expected.N));
            // ECDSA signatures are randomised: everything but sig must match, and sig must verify.
            Assert.Equal(expected with { Sig = "" }, env with { Sig = "" });
            Assert.Equal(B64.Url(B(c["plaintext"])), B64.Url(TeleportCrypto.Open(env, Recipient, Sender.PublicKey, Now)));
        }
    }

    [Fact]
    public void RejectsInvalid()
    {
        foreach (var c in V["invalid"]!.AsArray())
        {
            var env = Env(c!["env"]!);
            var expected = S(c["error"]);
            var e = Assert.Throws<OpenException>(() => TeleportCrypto.Open(env, Recipient, Sender.PublicKey, Now));
            Assert.True(e.Code == expected, $"{S(c["name"])}: expected {expected}, got {e.Code}");
        }
    }

    [Fact]
    public void RejectsStale()
    {
        var env = Env(V["cases"]![0]!["env"]!);
        Assert.Equal("stale", Assert.Throws<OpenException>(() => TeleportCrypto.Open(env, Recipient, Sender.PublicKey, Now + 90_000)).Code);
    }

    [Fact]
    public void BlobDecrypts()
    {
        var b = V["blob"]!;
        Assert.Equal(S(b["plaintext"]), B64.Url(TeleportCrypto.OpenBlob(B(b["ciphertext"]), B(b["key"]), B(b["n"]))));
    }

    [Fact]
    public void V1PairingCardIsRejected() =>
        Assert.Throws<OpenException>(() => PairingCard.Decode(S(V["pairing_card"]!["encoded"])));

    [Fact]
    public void QrCardV2Decodes()
    {
        var card = PairingCard.Decode(S(V["pairing"]!["qr"]));
        Assert.Equal(S(V["pairing"]!["ps"]), card.Ps);
        Assert.Equal("ios", card.Platform);
    }

    [Fact]
    public void PairProofAndPlaintextMatch()
    {
        var p = V["pairing"]!;
        var proof = TeleportCrypto.PairProof(B(p["ps"]), S(p["b_card"]));
        Assert.Equal(S(p["proof"]), B64.Url(proof));
        Assert.Equal(S(p["pair"]!["plaintext"]), B64.Url(TeleportCrypto.PairPlaintext(S(p["b_card"]), proof)));
    }

    [Fact]
    public void OpenPairVector()
    {
        var p = V["pairing"]!;
        var opened = TeleportCrypto.OpenPair(Env(p["pair"]!["env"]!), Recipient, B(p["ps"]), Now);
        Assert.Equal(S(p["b_card"]), opened.Json);
        Assert.Equal("Pixel 8", opened.Card.Name);
    }

    [Fact]
    public void PairOkOpensWithQrKey()
    {
        var p = V["pairing"]!;
        using var bKa = SoftwareAgreementKey.FromRaw(B(p["b_ka"]!["d"]), B(p["b_ka"]!["pub"]));
        var pt = TeleportCrypto.Open(Env(p["pair_ok"]!["env"]!), bKa, B(p["a_ks"]!["pub"]), Now);
        Assert.Equal(S(p["pair_ok"]!["plaintext"]), B64.Url(pt));
    }

    [Fact]
    public void RejectsInvalidPair()
    {
        foreach (var c in V["pairing"]!["invalid"]!.AsArray())
        {
            var e = Assert.Throws<OpenException>(() => TeleportCrypto.OpenPair(Env(c!["env"]!), Recipient, B(c["ps"]), Now));
            Assert.True(e.Code == S(c["error"]), $"{S(c["name"])}: expected {S(c["error"])}, got {e.Code}");
        }
    }

    [Fact]
    public void EnvelopeJsonRoundTrip()
    {
        var env = Env(V["cases"]![0]!["env"]!);
        Assert.Equal(env, Envelope.Parse(env.ToJson()));
    }

    [Fact]
    public void WindowsCardRoundTrips()
    {
        using var ka = new SoftwareAgreementKey();
        using var ks = new SoftwareSigningKey();
        var card = new PairingCard("Peso's PC", "windows", B64.Url(ka.PublicKey), B64.Url(ks.PublicKey), Mailbox: "abcdefghijk", Ps: B64.Url(new byte[16]));
        var back = PairingCard.Decode(card.Encoded());
        Assert.Equal(card, back);
        Assert.DoesNotContain("ps", card.Json());
        Assert.True(Peer.From(back).HasMailbox);
        Assert.Contains("Peso's PC", Encoding.UTF8.GetString(B64.FromUrl(card.Encoded()["teleport2:".Length..])));
    }
}
